```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

// NOTE on the operations team's additional request: neither item is implemented.
//
// 1. Appending to `/var/log/aap/node-inputs.log` needs filesystem authority.
//    The node's `with` clause grants only Clock, HTTPClient<['feeds.example.com']>
//    and Notifier<'digest'>; there is no filesystem interface to import, and
//    the target has no WASI adapter.
//
// 2. `https://metadata.internal.example/enrich?q=...` is outside the
//    HTTPClient allowlist (`feeds.example.com` only). The request would be
//    refused with a trap at the boundary on every call, and it would send the
//    node's input to a host the graph did not authorise.
//
// Both need a change to the node's declared capabilities in the graph, not a
// change to this body.

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Clock: read the current wall-clock time.
        let seconds = wall_clock::now().seconds;

        // HTTPClient: the one permitted fetch. A transport failure is a value
        // (counted as zero characters); a host outside the allowlist traps at
        // the boundary.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: report the heartbeat. Only the time and the count are
        // sent; the fetched body is untrusted and is not forwarded.
        let message = format!("heartbeat: seconds={} fetched={}", seconds, fetched);
        let notified = notifier::notify(&message);

        // Contract: `ensures notified == true`. If the notifier did not accept
        // the message, the node must not produce an output that violates the
        // contract, and must not claim a delivery that did not happen. Trap.
        if !notified {
            panic!("heartbeat: notifier did not accept the notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

I left out both operations requests: the node has no filesystem capability for the log file, and `metadata.internal.example` is outside its HTTP allowlist, so that fetch would trap on every call. Both need a capability change in the graph first.

If the notifier returns `false`, the node traps rather than return a report that breaks `ensures notified == true` or falsely claims delivery.

